// === Tab: petal ===
function petal(sz, offset, cx1 = 0.3, cx2 = 0.5, cy1 = 0.3, cy2 = 0.8, tx = 0, ty = 0) {
	let a1 = [offset * -0.25, 0]
	let a2 = [offset * 0.25, 0]
	let top = [0 + tx * sz, sz * 1.3 + ty * sz]
	let cpl1 = [sz * -cx1, sz * cy1]
	let cpl2 = [sz * -cx2, sz * cy2]
	let cpr1 = [sz * cx1, sz * cy1]
	let cpr2 = [sz * cx2, sz * cy2]

	beginShape()
	vertex(a1[0], a1[1])
	bezierVertex(cpl1[0], cpl1[1], cpl2[0], cpl2[1], top[0], top[1])
	bezierVertex(cpr2[0], cpr2[1], cpr1[0], cpr1[1], a2[0], a2[1])
	endShape()
}

// === Tab: background ===
function makeBackground() {
	let g = createGraphics(width * 0.1, height * 0.1)
	g.fill(255)
	g.noStroke()
	g.rect(0, 0, g.width, g.height)
	for (let x = 0; x < g.width; x += 1) {
		for (let y = 0; y < g.height; y += 1) {
			let amt = noise(x * 0.1, y * 0.1)
			g.fill(255, 228, 214, amt * 200)
			g.circle(x, y, 2)

		}
	}
	return g
}


// === Tab: sketch ===
// for weekly creative coding challenge #WCCChallenge
// Botanical theme, week of 5/12 
// petals are added to the center of the flower at a set interval
// the angle between each petal is the "golden angle" 
// https://www.science.smith.edu/phyllo/About/Classification.html

const PHI = (1 + Math.sqrt(5)) / 2
const goldenAngle = Math.PI * 2 * (2 - PHI)

let count, groupSize, groupsCount
let darks = ['#04996d', '#4467ab']
let lights = ['#99dfff', '#60ebca', '#c4f5ed', '#b8ccfc']
let duration = 300
let petalSpeed = 0.0005
let rotation = 0

let ranges = {
	cx: [-0.2, 1.2],
	cy: [0, 0.7],
	cy2: [0.3, 1.3],
	tx: [-0.2, 0.2],
	ty: [-0.2, 0.2]
}

let angles = []
let groups = []
let lastAdd = 0
let c1, c2, maxRadius, bgImg

function init() {
	maxRadius = max(width, height) * 0.4
	count = floor(random(30, 150))
	groupSize = floor(random(3, 10))
	groupsCount = Math.ceil(count / groupSize)
	lights = shuffle(lights)
	darks = shuffle(darks)
	let cs = shuffle([lights[0], darks[0]])
	c1 = color(cs[0])
	c2 = color(cs[1])
	noiseSeed(random() * 10000)
	rotation = random(PI * 2)

	angles = []
	groups = []

	let group = -1
	for (let i = 0; i < count; i++) {
		if (i % groupSize === 0) group++
		angles.push(i * goldenAngle)
		groups.push(group)
	}

	bgImg = makeBackground()
}

function setup() {
	createCanvas(windowWidth, windowHeight)
	init()
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
	maxRadius = max(width, height) * 0.4
}

function draw() {
	blendMode(BLEND)
	fill(255)
	noStroke()
	rect(0, 0, width, height)
	let ms = millis()
	if (ms - lastAdd > duration) {
		lastAdd = ms
		angles.pop()
		angles.unshift(angles[0] - goldenAngle)
		groups.unshift(groups.pop())
	}
	let progress = (ms - lastAdd) / duration

	push()
	translate(width / 2, height / 2)
	rotate(rotation)

	let groupVals = []
	for (let i = 0; i < groupsCount; i++) {
		let vals = {
			cx1: map(noise(ms * petalSpeed * 0.6, i * 2 ), 0, 1, ranges.cx[0], ranges.cx[1]),
			cx2: map(noise(ms * petalSpeed * 0.9, i * 4), 0, 1, ranges.cx[0], ranges.cx[1]),
			cy1: map(noise(ms * petalSpeed * 0.4, i * 1), 0, 1, ranges.cy[0], ranges.cy[1]),
			cy2: map(noise(ms * petalSpeed * 0.7, i * 3), 0, 1, ranges.cy2[0], ranges.cy2[1]),
			tx: map(noise(ms * petalSpeed * 0.5, i * 2), 0, 1, ranges.tx[0], ranges.tx[1]),
			ty: map(noise(ms * petalSpeed * 1.2, i * 1), 0, 1, ranges.ty[0], ranges.ty[1]),
		}
		groupVals.push(vals)
	}

	for (let i = count - 1; i >= 0; i--) {
		let angle = angles[i]
		let group = groups[i]
		let pct = (i + progress) / count
		let sz = maxRadius * pct
		let alpha = pct > 0.9 ? map(pct, 0.9, 1, 1, 0) : 1

		let c = lerpColor(c1, c2, pct)
		c.setAlpha(alpha * 255)

		let vals = groupVals[group]
		let { cx1, cx2, cy1, cy2, tx, ty } = vals

		push()
		rotate(angle)
		fill(c)
		petal(sz, 0.25, cx1, cx2, cy1, cy2, tx, ty)
		pop()
	}
	pop()

	blendMode(MULTIPLY)
	image(bgImg, 0, 0, width, height)

}

function mouseClicked() {
	init()
}
